refentry.refsect1:
&reftitle.description;
public stringnullYaf_Controller_Abstract::getInvokeArg stringname
Retorna um único argumento de invocação da ação atual, dado seu nome. Argumentos de invocação são passados para a ação por meio de Yaf_Controller_Abstract::forward.

&reftitle.parameters;


  name


    O nome do argumento de invocação a obter.

  &reftitle.examples;

   Exemplo de Yaf_Controller_Abstract::getInvokeArg


<?php
class UserController extends Yaf_Controller_Abstract
{
    public function indexAction() {
        // encaminha para a ação profile deste controlador,
        // contendo argumentos de invocação
        $this->forward("profile", array("name" => "laruence"));
        return false; // encerra o fluxo atual
    }

    public function profileAction() {
        // obtém um argumento de invocação pelo nome
        var_dump($this->getInvokeArg("name"));
        var_dump($this->getInvokeArg("missing"));
    }
}
?>


   &example.outputs.similar;


